function sorted(sightings: readonly StoredFinding[]): RecordJson[] {
	return [...sightings].map((finding) => shareable(sighting(finding))).sort(byId) as unknown as RecordJson[];
}

// A static finding keeps its rule, place, snippet and trigger, which are the head's own, and none of its tool's text. Biome
// and tsc are rewritten too: a build from before issue #281 stored their text, and the label cannot say which build wrote it.
function sighting(finding: StoredFinding): StoredFinding {
	const { check } = finding.properties.source;
	if (!check.startsWith("static.")) return finding;
	const what = `${check} reports ${finding.ruleId} here. ${withheld}.`;
	return {
		...finding,
		message: { ...finding.message, text: what },
		properties: { ...finding.properties, explanation: { what, whyHere: withheld, whatToDo: withheld } },
	};
}

fit(findings: readonly Finding[]): Finding[] {
	const ordered = [...findings].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
	let full: number[];
	let bare: number[];
	try {
		full = ordered.map((finding) => bytes(finding.toJSON()));
		bare = ordered.map((finding) => bytes(finding.abridged(note(1)).toJSON()) - note(1).length);
	} catch (error) {
		if (error instanceof RecordError) return [...findings];
		throw error;
	}
	const count = ordered.length;
	const kept = [0];
	for (const size of full) kept.push(kept.at(-1)! + size);
	if (2 + Math.max(count - 1, 0) + kept[count]! <= this.bytes) return [...findings];
	// A note's length grows with the files it names, so these are its lengths, shortest first.
	const files = new Set(ordered.map((finding) => finding.properties.path)).size;
	const lengths = new Set(Array.from({ length: files }, (_, index) => note(index + 1).length));
	for (const length of lengths) {
		const shortened = this.#cut(ordered, full, bare, kept, length);
		if (shortened !== undefined) return findings.map((finding) => shortened.get(finding) ?? finding);
	}
	// The message names no finding's text, since a failed check's error reaches the shared record.
	throw new RecordError("recordTooLarge", tooLarge);
}

storable(): SharedRecord {
	if (Buffer.byteLength(this.bytes) > recordLimit) throw invalid(`a record is at most ${recordLimit} bytes`);
	return this;
}

